create extension if not exists pgcrypto;
create table if not exists connections (id uuid primary key default gen_random_uuid(),provider text unique not null,access_token text,refresh_token text,expires_at timestamptz,shop_id text,shop_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists orders (id uuid primary key default gen_random_uuid(),source text not null default 'manual',external_order_id text not null,status text not null default 'new',buyer_name text,buyer_email text,shipping_address jsonb not null default '{}'::jsonb,product_slug text,child_name text,character_label text,dedication text,quantity integer not null default 1,needs_review boolean not null default true,etsy_payload jsonb,etsy_transactions jsonb,proof_url text,interior_pdf_url text,cover_pdf_url text,lulu_print_job_id text,tracking_code text,carrier_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source,external_order_id));
create table if not exists product_assets (id uuid primary key default gen_random_uuid(),product_slug text not null,character_label text not null,asset_type text not null default 'interior',page_number integer not null,asset_url text not null,approved boolean not null default false,created_at timestamptz not null default now(),unique(product_slug,character_label,asset_type,page_number));
create table if not exists webhook_events (webhook_id text primary key,event_type text,payload jsonb,created_at timestamptz not null default now());
alter table connections enable row level security;alter table orders enable row level security;alter table product_assets enable row level security;alter table webhook_events enable row level security;
